/** Chimney x0..1 z20..23 to y15: veneer stack, stone brick shoulders at y10 (z20 south, z23 north), campfire smoke cap. */
function chimney(g) {
  for (let y = 0; y <= 9; y++) for (let x = 0; x <= 1; x++) for (let z = 20; z <= 23; z++) put(g, x, y, z, B.block(veneer(x, y, z)));
